package za.co.erraco.disputes;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class DisputeService { private final TransactionRepository transactions; private final DisputeRepository disputes; DisputeService(TransactionRepository t,DisputeRepository d){transactions=t;disputes=d;} public List<Transaction> transactions(){return transactions.findAll();} @Transactional public Dispute dispute(Long id,String reason){var t=transactions.findById(id).orElseThrow(()->new TransactionNotFoundException(id));if(!"POSTED".equals(t.status))throw new TransactionNotEligibleException();t.status="DISPUTED";var d=new Dispute();d.transaction=t;d.reason=reason.trim();return disputes.save(d);} public List<Dispute> disputes(){return disputes.findAll();} static class TransactionNotFoundException extends RuntimeException{TransactionNotFoundException(Long id){super("Transaction "+id+" was not found");}} static class TransactionNotEligibleException extends RuntimeException{TransactionNotEligibleException(){super("Only posted transactions can be disputed");}}}
